# ---------------- numeric thresholds cheat sheet ----------------
def TH(tid, name, value, source, cat, note='', conf='high'):
    R.append(C('threshold.' + tid, name, source.split('(')[0].strip(), '', f'{name}: {value}.' + (f' {note}' if note else ''), '', f'Check: {name} meets {value}.', 'deterministic / screen', value, source, cat, 'Numeric threshold',
               conf=conf, source_set='Curated: numeric thresholds', sev='major'))
TH('contrast-text', 'Text contrast (normal text)', '≥ 4.5:1 (AA); ≥ 7:1 (AAA)', 'WCAG 2.2 SC 1.4.3 / 1.4.6 (W3C 2023)', 'Accessibility')
TH('contrast-large', 'Text contrast (large text ≥ 18pt or ≥ 14pt bold, ≈ 24px / 18.66px bold)', '≥ 3:1 (AA); ≥ 4.5:1 (AAA)', 'WCAG 2.2 SC 1.4.3 / 1.4.6', 'Accessibility')
TH('contrast-ui', 'Non-text contrast (UI components, focus indicators, meaningful graphics)', '≥ 3:1 against adjacent colors', 'WCAG 2.2 SC 1.4.11', 'Accessibility')
TH('target-min', 'Pointer target size (minimum)', '≥ 24×24 CSS px or 24 px spacing circle', 'WCAG 2.2 SC 2.5.8', 'Mobile & touch')
TH('target-enh', 'Pointer target size (enhanced)', '≥ 44×44 CSS px', 'WCAG 2.2 SC 2.5.5', 'Mobile & touch')
TH('target-ios', 'iOS minimum hit target', '≥ 44×44 pt', 'Apple Human Interface Guidelines', 'Mobile & touch')
TH('target-android', 'Android/Material touch target', '≥ 48×48 dp (with ≥ 8 dp spacing)', 'Google Material Design guidelines', 'Mobile & touch')
