TH('text-resize', 'Text resize without loss of content/function', 'up to 200%', 'WCAG 2.2 SC 1.4.4', 'Accessibility')
TH('reflow', 'Reflow without 2D scrolling', 'at 320 CSS px width (= 1280 px at 400% zoom) / 256 px height', 'WCAG 2.2 SC 1.4.10', 'Accessibility')
TH('text-spacing', 'Text spacing overrides must not break content', 'line-height 1.5× font size; paragraph spacing 2×; letter spacing 0.12×; word spacing 0.16×', 'WCAG 2.2 SC 1.4.12', 'Accessibility')
TH('line-length', 'Line length (measure)', '45–75 characters ideal (≈ 66); ≤ 80 characters (WCAG AAA)', 'Bringhurst (1992) The Elements of Typographic Style; WCAG 2.2 SC 1.4.8', 'Visual design & layout')
TH('line-height', 'Body text line height', '≈ 1.4–1.6× font size (≥ 1.5 for WCAG AAA)', 'WCAG 2.2 SC 1.4.8; typographic practice', 'Visual design & layout')
TH('body-font', 'Body font size on web/mobile', '≥ 16 px (CSS) body text; iOS default 17 pt; avoid < 12 px', 'Common practice; Apple HIG; Google Lighthouse legibility checks', 'Visual design & layout', conf='medium')
