# ---------------- evaluation & research methods ----------------
def ME(mid, name, author, year, desc, when, cite, sample='', conf='high'):
    R.append(C('method.' + mid, name, author, year, desc, when, '', 'method', sample, cite, 'Research & evaluation methods', 'Method',
               conf=conf, source_set='Curated: research & evaluation methods', sev='n/a', applies='design & research process'))
ME('heuristic-evaluation', 'Heuristic evaluation', 'Jakob Nielsen & Rolf Molich', 1990, 'Experts independently inspect an interface against a set of usability heuristics, then aggregate and rate findings by severity.', 'Fast, cheap inspection at any stage; complements but does not replace user testing.', 'Nielsen & Molich (1990). CHI \'90.', '3–5 evaluators')
ME('cognitive-walkthrough', 'Cognitive walkthrough', 'Clayton Lewis, Peter Polson, Cathleen Wharton & John Rieman', 1990, 'Evaluators step through a task asking whether a new user would know what to do and whether feedback shows progress.', 'Evaluating learnability for first-time or walk-up-and-use systems.', 'Wharton et al. (1994).')
ME('pluralistic-walkthrough', 'Pluralistic walkthrough', 'Randolph Bias', 1994, 'Users, developers and usability experts step through a scenario together, each recording what they would do before discussion.', 'Early design reviews with mixed stakeholders.', 'Bias, R. G. (1994). The pluralistic usability walkthrough. In Nielsen & Mack (Eds.), Usability Inspection Methods.')
